<?php
declare(strict_types=1);
require __DIR__.'/common.php';$u=cloud_user();video_post();$d=null;$relative=null;$cover=null;$committed=false;
try{
    $file=$_FILES['film']??null;if(!is_array($file)||($file['error']??null)!==UPLOAD_ERR_OK||!is_string($file['tmp_name']??null)||!is_uploaded_file($file['tmp_name']))throw new InvalidArgumentException('Nie udało się przesłać MP4. Sprawdź wybrany plik i limit hostingu.');
    video_mp4($file['tmp_name'],(string)$file['name']);$title=video_text(posted('title'),250,'Tytuł');$director=video_text(posted('director'),250,'Reżyser');$genre=video_id(posted('genre'));$subtitles=posted('subtitles');$description=trim(posted('description'));if(!mb_check_encoding($description,'UTF-8')||mb_strlen($description)>10000)throw new InvalidArgumentException('Opis może mieć maksymalnie 10000 znaków.');
    $subtitleFile=$_FILES['subtitle_file']??null;if(is_array($subtitleFile)&&($subtitleFile['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE){if($subtitleFile['error']!==UPLOAD_ERR_OK||!is_uploaded_file($subtitleFile['tmp_name'])||filesize($subtitleFile['tmp_name'])>60000)throw new InvalidArgumentException('Wybierz plik napisów SRT lub VTT do 60 KB.');$subtitles=file_get_contents($subtitleFile['tmp_name']);}
    if(!mb_check_encoding($subtitles,'UTF-8')||strlen($subtitles)>60000)throw new InvalidArgumentException('Napisy muszą być w UTF-8 i mieć maksymalnie 60 KB.');
    $d=db();$d->begin_transaction();$s=$d->prepare('SELECT idft FROM z6v_filmtype WHERE idft=?');$s->bind_param('i',$genre);$s->execute();if(!$s->get_result()->num_rows)throw new InvalidArgumentException('Wybierz gatunek.');$s->close();
    $relative=video_store($file['tmp_name'],$u['username']);$cover=video_form_cover($u['username']);
    $s=$d->prepare('INSERT INTO z6v_film(title,director,idu,filename,subtitles,idft,coverfilename) VALUES (?,?,?,?,?,?,?)');$s->bind_param('ssissis',$title,$director,$u['id'],$relative,$subtitles,$genre,$cover);$s->execute();$id=(int)$d->insert_id;$s->close();$duration=video_duration(FILMS_DIR.'/'.$relative);$s=$d->prepare('UPDATE z6v_film SET duration_seconds=?,description=? WHERE idf=?');$s->bind_param('isi',$duration,$description,$id);$s->execute();$s->close();$d->commit();$committed=true;$d->close();$d=null;video_flash('success','Dodano film.');redirect('film.php?id='.$id);
